    dict(fb='245088115244762', title='Stage de danse forró inter/avancé avec Madame Forró', date='2023-11-18', end=None, place='Ferme Couronnée, rue Pitre Grenapin, Saint-Nazaire', desc='Stage de danse forró niveau intermédiaire/avancé, par Madame Forró. Thème : connexion, trava (blocage) et musicalité. Vous aborderez les variations rythmiques et explorerez la connexion. De 14h à 16h.'),
    dict(fb='1706496896472313', title='Ateliers de danse brésilienne pour enfants (4-6 ans et 7-12 ans)', date='2023-05-14', end=None, place='Salle des Hibiscus, rue des Hibiscus, Saint-Nazaire', desc="Voyage dans l'univers des danses du Nordeste brésilien adapté aux enfants ! Dirigé par Alise Marieta. 10h-11h : 4-6 ans. 11h-12h : 7-12 ans."),
    dict(fb='965114637826251', title='Stage de danse forró avec Alise Marieta', date='2023-05-14', end=None, place='Salle des Hibiscus, rue des Hibiscus, Saint-Nazaire', desc='Un stage de danse forró de 2h sur les thèmes de la musicalité et de la qualité de la danse, dirigé par Alise Marieta. Six mois de pratique requis, maîtrise des pas de base demandée. De 14h à 16h.'),
    dict(fb='2472825442883666', title='Atelier Batucada Forró avec Julian Biblocq', date='2023-04-16', end=None, place='Maison de quartier Avalix, 3 rue du Docteur Albert Calmette, Saint-Nazaire', desc='Atelier batucada forró avec Julian Biblocq, mestre de batucada. Niveau requis : au moins un an de pratique de la musique (percussions, instrument, batucada…). De 14h30 à 17h. Organisé avec Aline Le Masson.'),
    dict(fb='1647904365643397', title='Stages de danse forró avec Tatiana Barros', date='2023-02-25', end=None, place='Espace civique Dubé, 1 rue des Ajoncs, Saint-Nazaire', desc='Atelier débutant 13h30-14h30 (10 €). Atelier niveau 1 14h45-16h15 : pas de base requis. Atelier niveau 2 16h30-18h : au moins un an de forró, orienté roots. 15 €/cours. Suivi du concert de Saíra le soir.'),
    dict(fb='3304120946502771', title='Musique et percussion corporelle brésilienne pour les enfants', date='2023-02-05', end=None, place='3 rue des Hibiscus, Saint-Nazaire', desc='10h-11h : 3-6 ans. 11h-12h : 7-12 ans. Un parc de petites percussions à main, en présence de Gabriel Lesoeur, animateur musicien, et de son accordéon. Prix libre entre 5 et 10 €. Réservation nécessaire.'),
    dict(fb='3274115272809523', title='Stage de musique forró (niveau intermédiaire) avec Gabriel Lesoeur', date='2023-01-08', end=None, place='Les Landettes, Saint-Nazaire', desc='Vous connaissez déjà le forró, le baião, le xote ? Vous avez déjà pratiqué le triangle, la zabumba et le ganza ? Vous aimez chanter ? Venez découvrir le forró selon Gabriel Lesoeur. 15 €, réservation obligatoire. De 16h45 à 18h45.'),
    dict(fb='614964670381930', title='Stage de percussion corporelle et chant forró (pour tous)', date='2023-01-08', end=None, place='Les Landettes, Saint-Nazaire', desc="Plongez dans l'univers rythmique du bal brésilien à travers la percussion corporelle et le chant. Au programme : ciranda, xote, baião, arrastapé. Dirigé par Gabriel Lesoeur. Accessible à tous. 15 €, réservation obligatoire. De 14h30 à 16h30."),
    dict(fb='1173540123514593', title='Stage de danses du Nordeste avec Alise et Gabiju', date='2022-11-06', end=None, place='Maison de quartier Chesnaie-Trébale, Saint-Nazaire', desc='Un stage de danses du Nordeste brésilien (arrastapé, xote, baião, coco, ciranda) à travers la danse et les percussions corporelles, dirigé par Alise Marieta et Gabriel Lesoeur. Minimum 10 €, le juste prix 20 €. De 13h30 à 15h30.'),
    dict(fb='1526633447779974', title='Stage de percussions corporelles et musique forró', date='2022-11-06', end=None, place='Maison de quartier de la Bouletterie, 29 rue des Frênes, Saint-Nazaire', desc="Plongez dans l'univers rythmique du bal brésilien à travers la percussion corporelle et le chant. Au programme : ciranda, xote, baião, arrastapé. Minimum 10 €, le juste prix 20 €. De 16h à 18h."),
    dict(fb='1443374232821741', title='Stage de forró avec Alise Marieta (niveau intermédiaire)', date='2022-11-06', end=None, place='Maison de quartier Chesnaie-Trébale, Saint-Nazaire', desc='Stage de forró universitaire de 2h, niveau intermédiaire, ouvert à toute personne maîtrisant les pas et figures de base. Dirigé par Alise Marieta : postures de guide et de suiveur, connexion en couple fermé ou ouvert. De 15h45 à 17h45.'),
    dict(fb='644671200653056', title='Stage de musique forró avec Leandro Campanha', date='2022-10-09', end=None, place='Les Landettes, Saint-Nazaire', desc="À l'occasion du Gros Week-end forró, nous accueillons le Brésilien Leandro Campanha, percussionniste spécialiste du forró. Découvrez et pratiquez cette musique populaire du Nordeste : zabumba, triangle, pandeiro, agogô, ganza. 25 €, limité à 10 participants, 2h30."),
    dict(fb='768038717619644', title="Stage d'initiation à la danse forró", date='2022-10-08', end=None, place='Le Garage, Saint-Nazaire', desc='Dans le cadre du Gros Week-end forró, ce stage pour découvrir les bases du forró, avant le grand concert du soir. Accessible à tous, même sans aucune connaissance. De 11h à 12h30 : 15 €. Dirigé par Alice et Julien.'),
    dict(fb='815930316254814', title='Stage de danse forró avec Rudolfo Batista', date='2022-10-08', end=None, place='Le Garage, Saint-Nazaire', desc='Pour notre Gros Week-end forró, nous recevons Rudolfo Batista, danseur, pédagogue, musicien et tourneur, qui a grandi à Olinda dans le Nordeste brésilien. À partir de 14h.'),
    dict(fb='1080391102539979', title='Atelier de pandeiro débutant', date='2022-03-30', end=None, place='École Carnot, Saint-Nazaire', desc='Atelier de pandeiro pour débutants. Sept places pour sept pandeiros ; si vous en apportez un, la jauge augmente. Participation à partir de 3 €. De 18h à 19h.'),
    dict(fb='709517790432121', title='Stage de musique forró avancé', date='2022-03-20', end=None, place='Saint-Nazaire', desc='Venez jouer du forró avec Léo Corrêa et Aline Le Masson (Forró Na Chuva). Ce stage est réservé aux musiciens qui connaissent déjà le forró. Tout instrument bienvenu. De 14h30 à 17h.'),
    dict(fb='1316524478815786', title='Atelier de musique forró débutant avec Cacau', date='2022-03-19', end=None, place='Saint-Nazaire', desc="Que vous soyez néophyte ou musicien chevronné, venez participer à cet atelier dirigé par Cacau Moutinho. 10 personnes maximum, 2h d'atelier : 20 €. Réservation obligatoire. De 11h à 13h."),
    dict(fb='297689038530479', title='Atelier de musique forró (tout instrument) avec Léo Corrêa', date='2021-10-23', end=None, place='Saint-Nazaire', desc="Quel que soit votre instrument de musique favori, venez participer aux ateliers forró de Léo ! Ce sera l'occasion de monter un groupe de forró éphémère : vous apprendrez à jouer deux ou trois forrós avec style. De 14h30 à 18h."),
    dict(fb='185939385800215', title='Atelier forró à Pornichet', date='2020-01-25', end=None, place='Hôtel Le Danicheff, Pornichet', desc="En complément de l'atelier d'initiation du dimanche, nous proposons ponctuellement des ateliers de 6 à 10 participants. Sur réservation. Participation : 5 €. 1h d'atelier + 30 min de pratique. De 17h à 18h30."),
